package main

import (
	"log"
	"net/http"
)

type recorder struct {
	http.ResponseWriter
	code int
}

func (r *recorder) WriteHeader(code int) {
	r.code = code
	r.ResponseWriter.WriteHeader(code)
}

func withAccessLog(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		rec := &recorder{ResponseWriter: w, code: http.StatusOK}
		next.ServeHTTP(rec, req)
		code := rec.code
		log.Printf("status: %d", code)
	})
}

func clampStatus(code int) int {
	if code < 100 {
		code = 500
	}
	log.Printf("status: %d", code)
	if code > 599 {
		code = 500
	}
	return code
}

func main() {
	http.ListenAndServe(":8080", withAccessLog(http.NotFoundHandler()))
}

package main

import (
	"log"
	"time"
)

func reportDepth(jobs chan string) {
	t := time.NewTicker(time.Minute)
	defer t.Stop()
	for range t.C {
		pending := len(jobs)
		log.Printf("pending: %d", pending)
	}
}

func popBatch(jobs chan string, limit int) []string {
	var out []string
	for len(out) < limit {
		select {
		case j := <-jobs:
			out = append(out, j)
			pending := len(out)
			log.Printf("pending: %d", pending)
		default:
			return out
		}
	}
	return out
}

func main() {
	jobs := make(chan string, 100)
	go reportDepth(jobs)
	popBatch(jobs, 10)
}

