import (
	"io"
	"log"
	"os"
)

func archiveFile(dst, src string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()
	n, err := io.Copy(out, in)
	if err != nil {
		return err
	}
	log.Printf("bytes: %d", n)
	return nil
}

func readFrame(r io.Reader) []byte {
	var buf []byte
	one := make([]byte, 1)
	for {
		n, err := r.Read(one)
		if n == 0 || err != nil {
			break
		}
		log.Printf("bytes: %d", n)
		if one[0] == '\n' {
			break
		}
		buf = append(buf, one[0])
	}
	return buf
}

func main() {
	archiveFile("out.bin", "in.bin")
}

package main

import (
	"log"
	"sync"
	"time"
)

type entry struct {
	val     string
	expires time.Time
}

type Cache struct {
	mu    sync.Mutex
	items map[string]entry
}

func (c *Cache) sweepLoop() {
	for range time.Tick(30 * time.Second) {
		c.mu.Lock()
		evicted := 0
		for k, e := range c.items {
			if time.Now().After(e.expires) {
				delete(c.items, k)
				evicted++
			}
		}
		c.mu.Unlock()
		log.Printf("evicted %d", evicted)
	}
}

func (c *Cache) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.items[key]
	if ok && time.Now().After(e.expires) {
		delete(c.items, key)
		evicted := len(c.items)
		log.Printf("evicted %d", evicted)
		return "", false
	}
	return e.val, ok
}

func main() {
	c := &Cache{items: map[string]entry{}}
	go c.sweepLoop()
	c.Get("a")
}

