import (
	"log"
	"time"
)

func runAt(hour int, task func()) {
	for {
		now := time.Now()
		next := time.Date(now.Year(), now.Month(), now.Day(), hour, 0, 0, 0, now.Location())
		if !next.After(now) {
			next = next.Add(24 * time.Hour)
		}
		wait := time.Until(next)
		log.Printf("next run in %v", wait)
		time.Sleep(wait)
		task()
	}
}

func nextWeekday(now time.Time, day time.Weekday) time.Duration {
	t := now
	for t.Weekday() != day {
		t = t.Add(24 * time.Hour)
		wait := t.Sub(now)
		log.Printf("next run in %v", wait)
	}
	return t.Sub(now)
}

func main() {
	runAt(3, func() {})
}

package main

import (
	"encoding/json"
	"log"
	"os"
)

type Config struct {
	Addr    string
	Workers int
}

func loadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	cfg := &Config{}
	if err := json.Unmarshal(data, cfg); err != nil {
		return nil, err
	}
	log.Printf("config: %+v", cfg)
	return cfg, nil
}

func withDefaults(cfg *Config) *Config {
	if cfg.Workers <= 0 {
		cfg.Workers = 4
	}
	log.Printf("config: %+v", cfg)
	if cfg.Addr == "" {
		cfg.Addr = ":8080"
	}
	return cfg
}

func main() {
	cfg, _ := loadConfig("app.json")
	withDefaults(cfg)
}

package main

import (
	"log"
	"os"
	"path"
)

func copyOne(src, dst string) error {
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	return os.WriteFile(dst, data, 0o644)
}

func syncDir(src, dst string) error {
	entries, err := os.ReadDir(src)
	if err != nil {
		return err
	}
	count := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if err := copyOne(path.Join(src, e.Name()), path.Join(dst, e.Name())); err != nil {
			return err
		}
		count++
	}
	log.Printf("processed %d files", count)
	return nil
}

func globMatches(pattern string, names []string) []string {
	var out []string
	for _, n := range names {
		if ok, _ := path.Match(pattern, n); ok {
			out = append(out, n)
		}
		count := len(out)
		log.Printf("processed %d files", count)
	}
	return out
}

func main() {
	syncDir(os.Args[1], os.Args[2])
}

