import (
	"database/sql"
	"log"
)

func purgeSessions(db *sql.DB) error {
	res, err := db.Exec("DELETE FROM sessions WHERE expires_at < now()")
	if err != nil {
		return err
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return err
	}
	log.Printf("rows: %d", affected)
	return nil
}

func collectIDs(rows *sql.Rows) []int {
	var ids []int
	for rows.Next() {
		var id int
		rows.Scan(&id)
		ids = append(ids, id)
		affected := len(ids)
		log.Printf("rows: %d", affected)
	}
	return ids
}

func main() {
	db, _ := sql.Open("postgres", "dbname=app")
	purgeSessions(db)
}

