import (
	"log"
	"time"
)

func runJob(fn func() error) bool {
	start := time.Now()
	err := fn()
	elapsed := time.Since(start)
	log.Printf("job took %v", elapsed)
	return err == nil
}

func backoff(attempt int) time.Duration {
	elapsed := time.Duration(1<<attempt) * 100 * time.Millisecond
	log.Printf("job took %v", elapsed)
	if elapsed > 10*time.Second {
		elapsed = 10 * time.Second
	}
	return elapsed
}

func main() {
	for attempt := 0; !runJob(func() error { return nil }); attempt++ {
		time.Sleep(backoff(attempt))
	}
}

package main

import (
	"log"
	"sync"
	"time"
)

type Hub struct {
	mu    sync.Mutex
	conns map[string]chan []byte
}

func (h *Hub) heartbeat() {
	for range time.Tick(time.Minute) {
		h.mu.Lock()
		clients := len(h.conns)
		h.mu.Unlock()
		log.Printf("clients: %d", clients)
	}
}

func (h *Hub) broadcast(msg []byte) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for id, ch := range h.conns {
		clients := len(ch)
		log.Printf("clients: %d", clients)
		select {
		case ch <- msg:
		default:
			delete(h.conns, id)
		}
	}
}

func main() {
	h := &Hub{conns: map[string]chan []byte{}}
	go h.heartbeat()
	h.broadcast([]byte("hi"))
}
